        'pt_BR' => 'Cookies analíticos/de marketing não essenciais só serão ativados após o consentimento; cookies estritamente necessários são exceção.',
        'pt_PT' => 'Os cookies analíticos/de marketing não essenciais só serão ativados após o consentimento; os cookies estritamente necessários são exceção.',
